export const meta = {
  name: 'qa-and-docs',
  description: 'Detect stack → index shipped code → extract acceptance criteria → generate a traceable QA/test plan AND user/dev docs → grade against the code, across one or more repos',
  whenToUse: 'When code has shipped (possibly outside this framework) and you need a standalone, traceable QA/test plan + documentation grounded in acceptance criteria — without re-running the whole feature pipeline. Pass a scope: { spec:"<id>" } | { paths:["glob",...] } | { gitRange:"a..b" } | a feature name string.',
  phases: [
    { title: 'Detect', detail: 'Identify stack(s) and repo layout', model: 'sonnet' },
    { title: 'Index', detail: 'Bottom-up map of in-scope code: files → methods/routes → features', model: 'sonnet' },
    { title: 'Criteria', detail: 'Extract or infer testable acceptance criteria (the trace anchors)', model: 'opus' },
    { title: 'QAPlan', detail: 'Traceable test plan: each case links to code + criterion', model: 'opus' },
    { title: 'Docs', detail: 'Generate/update user + dev docs grounded in real code', model: 'sonnet' },
    { title: 'Grade', detail: 'Verifier scores completeness/helpfulness/truthfulness; coverage gate', model: 'opus' },
    { title: 'Report', detail: 'Coverage matrix + grade + locations', model: 'opus' },
  ],
}

const WRITER_AGENT = 'general-purpose'

const isObj = args && typeof args === 'object'
const featureName = typeof args === 'string' ? args : (isObj && args.feature) || ''
const specArg = isObj ? args.spec || null : null
const specRef = specArg ? specRefValue(specArg) || null : null
const paths = (isObj && args.paths) || null
const gitRange = (isObj && args.gitRange) || null
const repoHints = (isObj && args.repos) || null

if (specArg && !specRef) {
  const error = 'spec reference is not a folder name or id. Fix: pass the folder name or id, e.g. { spec: "20261018-1430" }'
  log(error)
  return { error }
}
if (!featureName && !specRef && !paths && !gitRange) {
  log('Provide a scope: { spec:"<id>" } | { paths:[...] } | { gitRange:"a..b" } | a feature name string.')
  return { error: 'missing scope' }
}
const scopeDesc = specRef ? `spec ${specRef}` : paths ? `paths ${JSON.stringify(paths)}` : gitRange ? `git range ${gitRange}` : featureName

